INSERT INTO `trinity_string2` (`entry`, `content_default`, `content_loc1`, `content_loc2`, `content_loc3`, `content_loc4`, `content_loc5`, `content_loc6`, `content_loc7`, `content_loc8`) VALUES (12200, '|cff00ffffYou already have this item!|r', NULL, '|cff00ffffVous avez déjà cet objet !|r', NULL, NULL, NULL, NULL, NULL, '|cff00ffffУ вас уже имеется данная вещь!|r');
INSERT INTO `trinity_string2` (`entry`, `content_default`, `content_loc1`, `content_loc2`, `content_loc3`, `content_loc4`, `content_loc5`, `content_loc6`, `content_loc7`, `content_loc8`) VALUES (12201, '|cff00ff00Payment complete. You need to do log-out by character and set a new name for character. Do not forget to clear folder Cache after rename!|r', NULL, '|cff00ff00Payment validé. Vous devez vous déconnecter de votre personnage et le renommer. N\'oubliez pas d\'effacer le dossier Cache après l\'avoir renommé !|r', NULL, NULL, NULL, NULL, NULL, '|cff00ff00Оплата успешно произведена. Сделайте логаут и введите новое имя своего персонажа.Не забудьте после смены имени, выйти из игры и удалить из клиента папку Cache!|r');
INSERT INTO `trinity_string2` (`entry`, `content_default`, `content_loc1`, `content_loc2`, `content_loc3`, `content_loc4`, `content_loc5`, `content_loc6`, `content_loc7`, `content_loc8`) VALUES (12202, '|cff00ff00Payment complete. You need to do log-out by character and set customize for character.Do not forget to clear folder Cache after rename!|r', NULL, '|cff00ff00Payment validé. Vous devez vous déconnecter de votre personnage et le personnaliser. N\'oubliez pas d\'effacer le dossier Cache après l\'avoir personnalisé !|r', NULL, NULL, NULL, NULL, NULL, '|cff00ff00Оплата успешно произведена. Сделайте логаут и измените внешность своего персонажа.Не забудьте после смены внешности, выйти из игры и удалить из клиента папку Cache!|r');
INSERT INTO `trinity_string2` (`entry`, `content_default`, `content_loc1`, `content_loc2`, `content_loc3`, `content_loc4`, `content_loc5`, `content_loc6`, `content_loc7`, `content_loc8`) VALUES (12203, '|cff00ff00Payment complete. You need to do log-out by character and change faction for character.Do not forget to clear folder Cache after rename!|r', NULL, '|cff00ff00Payment validé. Vous devez vous déconnecter de votre personnage et changer de faction. N\'oubliez pas d\'effacer le dossier Cache après l\'avoir changé de faction !|r', NULL, NULL, NULL, NULL, NULL, '|cff00ff00Оплата успешно произведена. Сделайте логаут и измените фракцию своего персонажа.Не забудьте после смены фракции, выйти из игры и удалить из клиента папку Cache!|r');
INSERT INTO `trinity_string2` (`entry`, `content_default`, `content_loc1`, `content_loc2`, `content_loc3`, `content_loc4`, `content_loc5`, `content_loc6`, `content_loc7`, `content_loc8`) VALUES (12204, '|cff00ff00Payment complete. You need to do log-out by character and change race for character.Do not forget to clear folder Cache after change race!|r', NULL, '|cff00ff00Payment validé. Vous devez vous déconnecter de votre personnage et changer de race. N\'oubliez pas d\'effacer le dossier Cache après avoir changé de race !|r', NULL, NULL, NULL, NULL, NULL, '|cff00ff00Оплата успешно произведена. Сделайте логаут и измените расу своего персонажа.Не забудьте после смены расы, выйти из игры и удалить из клиента папку Cache!|r');
INSERT INTO `trinity_string2` (`entry`, `content_default`, `content_loc1`, `content_loc2`, `content_loc3`, `content_loc4`, `content_loc5`, `content_loc6`, `content_loc7`, `content_loc8`) VALUES (12205, '|cffff0000You have not enough A.P. for payment!|r', NULL, '|cffff0000Vous n\'avez pas assez d\'A.P pour le payement !|r', NULL, NULL, NULL, NULL, NULL, '|cffff0000У вас недостаточно A.P. для совершения покупки!|r');
